  // ─── HTML Blocks (used with data-i18n-html) ──────────────────────
  'help.install_app_html':
    'MUSIXQUARE ಇಷ್ಟವಾಯಿತೆ? ಅದನ್ನು ಆ್ಯಪ್ ಆಗಿ ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಬಹುದು.<ul class="help-list"><li><strong>iOS:</strong> ಹಂಚಿಕೊಳ್ಳಿ → ಹೋಮ್ ಸ್ಕ್ರೀನ್‌ಗೆ ಸೇರಿಸಿ</li><li><strong>Android:</strong> ಮೆನು → ಆ್ಯಪ್ ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಿ</li><li><strong>Windows:</strong> ವಿಳಾಸ ಪಟ್ಟಿಯಲ್ಲಿರುವ ಇನ್‌ಸ್ಟಾಲ್ ಐಕಾನ್</li><li><strong>macOS:</strong> ಹಂಚಿಕೊಳ್ಳಿ → Dock ಗೆ ಸೇರಿಸಿ</li></ul>',
  'help.local_recommended_html':
    'ಒಂದೇ ನೆಟ್‌ವರ್ಕ್‌ನಲ್ಲಿ ಆಡಿಯೊ ಹಂಚಿಕೆ ಅತ್ಯಂತ ಸ್ಥಿರವಾಗಿರುತ್ತದೆ.<ul class="help-list"><li>ದೂರಸ್ಥ ಭಾಗವಹಿಸುವವರೂ ಅದೇ ವೈಶಿಷ್ಟ್ಯಗಳನ್ನು ಬಳಸಬಹುದು.</li><li>ದೂರಸ್ಥ ಭಾಗವಹಿಸುವವರು Cloudflare ಮಾರ್ಗಗಳನ್ನು ಬಳಸುತ್ತಾರೆ, ಆದ್ದರಿಂದ ನೆಟ್‌ವರ್ಕ್ ಪರಿಸ್ಥಿತಿಗೆ ಅನುಗುಣವಾಗಿ ವಿಳಂಬ ಹೆಚ್ಚಬಹುದು ಅಥವಾ ಆಡಿಯೊ ಸ್ವೀಕಾರ ವಿಫಲವಾಗಬಹುದು.</li><li>VPN ಅಥವಾ ನಿರ್ಬಂಧಿತ ನೆಟ್‌ವರ್ಕ್ ಸಂಪರ್ಕವನ್ನು ಅಸ್ಥಿರಗೊಳಿಸಬಹುದು.</li></ul>',
  'setup.how_to_connect_html':
    'ಸಂಪರ್ಕಿಸಲು ಹೋಸ್ಟ್‌ನ <strong>6-ಅಂಕಿಯ ಕೋಡ್</strong> ನಮೂದಿಸಿ.<ul class="help-list"><li><strong>ಹೋಸ್ಟ್:</strong> “ರೂಮ್ ರಚಿಸಿ” → ಕೋಡ್ ಪರಿಶೀಲಿಸಿ</li><li><strong>ಭಾಗವಹಿಸುವವರು:</strong> “ರೂಮ್‌ಗೆ ಸೇರಿ” → ಕೋಡ್ ನಮೂದಿಸಿ</li><li><strong>ಹೋಸ್ಟ್ ಸೇರಿ ಗರಿಷ್ಠ 100 ಸಾಧನಗಳು</strong> ಸಂಪರ್ಕಿಸಬಹುದು.</li></ul>',
  'player.play_speakers_html':
    'ಪ್ರತಿ ಭಾಗವಹಿಸುವವರು ಒಂದು <strong>ಪಾತ್ರ (ಔಟ್‌ಪುಟ್ ಚಾನಲ್)</strong> ಆರಿಸುತ್ತಾರೆ.<ul class="help-list"><li><strong>ಮಧ್ಯ:</strong> ಸ್ಟೀರಿಯೊ (ಡೀಫಾಲ್ಟ್) ಔಟ್‌ಪುಟ್</li><li><strong>ಎಡ:</strong> <bdi dir="ltr">L</bdi> ಚಾನಲ್ ಔಟ್‌ಪುಟ್</li><li><strong>ಬಲ:</strong> <bdi dir="ltr">R</bdi> ಚಾನಲ್ ಔಟ್‌ಪುಟ್</li><li><strong>ಸಬ್‌ವೂಫರ್:</strong> ಕಡಿಮೆ ಆವರ್ತನದ ಮಿಶ್ರ ಔಟ್‌ಪುಟ್</li></ul><strong>ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ</strong> ಪಾತ್ರಗಳನ್ನು ಯಾವಾಗ ಬೇಕಾದರೂ ಬದಲಿಸಬಹುದು.',
  'player.play_media_action_html':
    'ಹೋಸ್ಟ್‌ಗೆ 3 ಆಯ್ಕೆಗಳಿವೆ.<ul class="help-list"><li><strong>ಸ್ಥಳೀಯ ಫೈಲ್ ಲೋಡ್ ಮಾಡಿ:</strong> ನಿಮ್ಮ ಸಾಧನದಿಂದ ಸಂಗೀತ ಆರಿಸಿ. ನಿಖರ ಸಿಂಕ್ ಬೆಂಬಲಿತವಾಗಿದೆ</li><li><strong>ಒಟ್ಟಿಗೆ YouTube:</strong> ವೀಡಿಯೊಗಳು ಮತ್ತು ಪ್ಲೇಲಿಸ್ಟ್‌ಗಳು ಬೆಂಬಲಿತವಾಗಿವೆ. ಚಾನಲ್ ವಿಭಜನೆ ಅಥವಾ ಆಡಿಯೊ ಪರಿಣಾಮಗಳಿಲ್ಲ</li><li><strong>ಸಿಸ್ಟಮ್ ಆಡಿಯೊ ಹಂಚಿಕೆ:</strong> ಹೋಸ್ಟ್ ಕಂಪ್ಯೂಟರ್‌ನಲ್ಲಿ Chromium-ಆಧಾರಿತ ಬ್ರೌಸರ್ ಬಳಸುವಾಗ ಲಭ್ಯವಿದೆ</li></ul>',
  'help.need_help_html':
    '<ul class="help-list"><li><strong>ಕೋಡ್ ನಮೂದಿಸಿದರೂ ಸಂಪರ್ಕಿಸಲು ಆಗುತ್ತಿಲ್ಲ:</strong> ಕೋಡ್ ಪರಿಶೀಲಿಸಿ ಮತ್ತು ಸ್ವಲ್ಪ ಸಮಯದ ನಂತರ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ. ಕಂಪನಿ, ಶಾಲೆ ಅಥವಾ VPN ನೆಟ್‌ವರ್ಕ್ ಸಂಪರ್ಕವನ್ನು ನಿರ್ಬಂಧಿಸಬಹುದು.</li><li><strong>ಅಸ್ಥಿರ ಸಂಪರ್ಕ:</strong> ಸ್ಥಳೀಯ ಭಾಗವಹಿಸುವವರು ರೂಟರ್‌ಗೆ ಹತ್ತಿರ ಇರಲು ಪ್ರಯತ್ನಿಸಬೇಕು ಮತ್ತು ದೂರಸ್ಥ ಭಾಗವಹಿಸುವವರು ಸ್ಥಿರ ಇಂಟರ್ನೆಟ್ ಸಂಪರ್ಕ ಬಳಸಬೇಕು.</li><li><strong>ಇತರ ಸಮಸ್ಯೆಗಳು:</strong> ನೆಟ್‌ವರ್ಕ್ ಸ್ಥಿತಿ ಪರಿಶೀಲಿಸಿ ಮತ್ತು ಎಲ್ಲಾ ಸಾಧನಗಳಲ್ಲಿ ಆ್ಯಪ್ ಅನ್ನು ಮರುಪ್ರಾರಂಭಿಸಿ. ಪ್ರಶ್ನೆಗಳಿದ್ದರೆ <a href="/faq" target="_blank" rel="noopener noreferrer" style="color:inherit;text-decoration:underline">FAQ</a> ನೋಡಿ ಅಥವಾ ಅತ್ಯಂತ ಕೆಳಗಿರುವ ಇಮೇಲ್ ಮೂಲಕ ನಮ್ಮನ್ನು ಸಂಪರ್ಕಿಸಿ.</li></ul>',
